// EvilTokens device code phishing - inbox rules after a device code sign-in
// Defender XDR advanced hunting (CloudAppEvents needs Defender for Cloud Apps with the Microsoft 365 connector); <users> from the first query
let users = dynamic(["<user1@contoso.com>", "<user2@contoso.com>"]);
CloudAppEvents
| where Timestamp > ago(30d)
| where ActionType in ("New-InboxRule", "Set-InboxRule", "UpdateInboxRules")
| extend Upn = tolower(tostring(RawEventData.UserId))
| where Upn in (users)
| project Timestamp, Upn, ActionType, IPAddress, CountryCode, Parameters = tostring(RawEventData.Parameters)
| order by Timestamp desc

// Schema: https://learn.microsoft.com/en-us/defender-xdr/advanced-hunting-entraidspnsigninevents-table
let badIPs = dynamic(["144.172.64.128","144.172.64.99","144.172.64.60","187.15.88.186","187.15.90.217","187.15.89.186"]);
let badApps = dynamic(["506e08f9-6e9a-4da4-942b-a099a03644ae","24205314-2b89-4e07-a2a4-579e898a5640","0de14c77-b9b0-4137-9360-34878a929827"]);
EntraIdSpnSignInEvents
| where Timestamp >= datetime(2026-10-01)
| where IPAddress in (badIPs) or ApplicationId in (badApps) or UserAgent has_any ("Python-urllib/3.12","python-requests/2.31.0","python-requests/2.34.2","curl/7.88.1","azure-toolkit/1.0")
| summarize Attempts=count(), Failures=countif(ErrorCode != 0), FirstSeen=min(Timestamp), LastSeen=max(Timestamp) by ServicePrincipalName, ApplicationId, IPAddress, UserAgent
| order by LastSeen desc

// Teams help-desk impersonation to AD CS abuse - DCSync and Rclone renamed SearchApp.exe
// Defender XDR advanced hunting; Defender for Identity (IdentityDirectoryEvents) and Defender for Endpoint (DeviceProcessEvents)
IdentityDirectoryEvents
| where Timestamp > ago(30d)
| where ActionType == "Directory Services replication"
| project Timestamp, ActionType, AccountName, DeviceName, IPAddress, DestinationDeviceName, AdditionalFields;
DeviceProcessEvents
| where Timestamp > ago(30d)
| where ProcessVersionInfoOriginalFileName =~ "rclone.exe" and FileName !~ "rclone.exe"
| project Timestamp, DeviceName, AccountName, FileName, FolderPath, ProcessCommandLine

// Entra Connect Health metadata leak (Nov 2026): sign-ins of the exposed admin / technical-contact accounts since detection (9 Nov 2026)
// Microsoft Sentinel / Log Analytics - diagnostic categories SignInLogs AND NonInteractiveUserSignInLogs (token replay shows only in the latter)
// Country comes from LocationDetails: in AADNonInteractiveUserSignInLogs the Location column is the region of the resource, not the country
let admins = dynamic(["<admin1@contoso.com>", "<admin2@contoso.com>"]);   // the addresses Microsoft's GetTenant script lists for your tenant
let since = datetime(2026-11-09);
let signins = union isfuzzy=true
    (SigninLogs | extend Kind = "interactive"),
    (AADNonInteractiveUserSignInLogs | extend Kind = "non-interactive")
| where UserPrincipalName in~ (admins)
| extend Country = tostring(parse_json(tostring(LocationDetails)).countryOrRegion);
let known = signins
| where TimeGenerated between (ago(90d) .. since) and ResultType == "0"
| summarize KnownCountries = make_set(Country) by UserPrincipalName;
signins
| where TimeGenerated > since
| join kind=leftouter known on UserPrincipalName
| where RiskLevelDuringSignIn in ("medium", "high") or not(set_has_element(KnownCountries, Country))
| project TimeGenerated, Kind, UserPrincipalName, AppDisplayName, IPAddress, Country, RiskLevelDuringSignIn, RiskEventTypes_V2, ResultType, ResultDescription
| order by TimeGenerated desc

// M365 token spray and replay campaign (Huntress, 22 Oct 2026) - sign-ins from 193.26.115.0/24 and the named relays
// Microsoft Sentinel; diagnostic settings categories SignInLogs and NonInteractiveUserSignInLogs
let ranges = dynamic(["193.26.115.0/24"]);
let ips = dynamic(["124.198.132.33", "45.83.31.44", "192.159.99.172", "185.238.2.195", "167.148.41.96"]);
union SigninLogs, AADNonInteractiveUserSignInLogs
| where TimeGenerated > ago(180d)
| where ipv4_is_in_any_range(IPAddress, ranges) or IPAddress in (ips) or AutonomousSystemNumber == 210558
| project TimeGenerated, UserPrincipalName, IPAddress, AutonomousSystemNumber, AppDisplayName, AppId, ResourceDisplayName, UserAgent, ResultType, ResultDescription, Category
| order by TimeGenerated desc

// Teams booking flow device code phishing - who clicked the lure links
// Defender XDR advanced hunting; Defender for Office 365 Plan 2 (UrlClickEvents) and Defender for Endpoint (DeviceNetworkEvents)
let iocs = dynamic(["gpimmlgration.com", "share.google"]);
union isfuzzy=true
  (UrlClickEvents | where Timestamp > ago(60d) | where Url has_any (iocs) | project Timestamp, Who = AccountUpn, Url, ActionType, Source = "UrlClick"),
  (DeviceNetworkEvents | where Timestamp > ago(60d) | where RemoteUrl has_any (iocs) | project Timestamp, Who = InitiatingProcessAccountUpn, Url = RemoteUrl, ActionType, Source = "Endpoint")
| order by Timestamp desc
